import heapq
import math
from collections import deque


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _ensure_finite(obj):
    """Reject any NaN / Infinity nested anywhere in the payload."""
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite number found in payload")
    elif isinstance(obj, dict):
        for v in obj.values():
            _ensure_finite(v)
    elif isinstance(obj, list):
        for v in obj:
            _ensure_finite(v)


def _nonempty(value):
    return isinstance(value, str) and value.strip() != ""


def transform(payloads, contract):
    if contract.get("operation") != "trust_paths":
        raise ValueError("unsupported operation: %r" % contract.get("operation"))
    if not isinstance(payloads, list) or len(payloads) != 1:
        raise ValueError("trust_paths expects exactly one input payload")
    payload = payloads[0]
    _ensure_finite(payload)
    if not isinstance(payload, dict):
        raise ValueError("trust_paths payload must be an object")

    # ---- now ----
    if "now" not in payload:
        raise ValueError("missing 'now'")
    now = payload["now"]
    if not _is_int(now) or now < 0:
        raise ValueError("'now' must be an int >= 0")

    # ---- nodes ----
    if "nodes" not in payload:
        raise ValueError("missing 'nodes'")
    nodes = payload["nodes"]
    if not isinstance(nodes, list):
        raise ValueError("'nodes' must be a list")
    node_map = {}
    for n in nodes:
        if not isinstance(n, dict):
            raise ValueError("node must be an object")
        nid = n.get("id")
        if not _nonempty(nid):
            raise ValueError("node id must be a non-empty string")
        if nid in node_map:
            raise ValueError("duplicate node id: %r" % nid)
        expires = n.get("expires")
        if not _is_int(expires) or expires < 0:
            raise ValueError("node expires must be an int >= 0")
        revoked = n.get("revoked")
        if not isinstance(revoked, bool):
            raise ValueError("node revoked must be a bool")
        node_map[nid] = {"id": nid, "expires": expires, "revoked": revoked}

    # ---- roots ----
    if "roots" not in payload:
        raise ValueError("missing 'roots'")
    roots = payload["roots"]
    if not isinstance(roots, list):
        raise ValueError("'roots' must be a list")
    root_set = set()
    for r in roots:
        if not _nonempty(r):
            raise ValueError("root id must be a non-empty string")
        if r not in node_map:
            raise ValueError("root endpoint does not exist: %r" % r)
        root_set.add(r)

    # ---- edges ----
    if "edges" not in payload:
        raise ValueError("missing 'edges'")
    edges = payload["edges"]
    if not isinstance(edges, list):
        raise ValueError("'edges' must be a list")
    seen_pairs = set()
    edge_list = []
    for e in edges:
        if not isinstance(e, dict):
            raise ValueError("edge must be an object")
        issuer = e.get("issuer")
        subject = e.get("subject")
        if not _nonempty(issuer):
            raise ValueError("edge issuer must be a non-empty string")
        if not _nonempty(subject):
            raise ValueError("edge subject must be a non-empty string")
        if issuer not in node_map or subject not in node_map:
            raise ValueError("edge endpoint does not exist")
        expires = e.get("expires")
        if not _is_int(expires) or expires < 0:
            raise ValueError("edge expires must be an int >= 0")
        pair = (issuer, subject)
        if pair in seen_pairs:
            raise ValueError("duplicate edge: %r -> %r" % pair)
        seen_pairs.add(pair)
        edge_list.append((issuer, subject, expires))

    # ---- effective graph after revocation / expiry removal ----
    surviving = {
        nid for nid, nd in node_map.items()
        if (not nd["revoked"]) and nd["expires"] > now
    }
    graph = {nid: [] for nid in surviving}
    for issuer, subject, expires in edge_list:
        if expires > now and issuer in surviving and subject in surviving:
            graph[issuer].append((subject, expires))

    surviving_roots = [r for r in root_set if r in surviving]

