    for r in surviving_roots:
        val = node_map[r]["expires"]
        if val > dist[r]:
            dist[r] = val
            heapq.heappush(heap, (-val, r))
    while heap:
        neg, u = heapq.heappop(heap)
        d = -neg
        if d < dist[u]:
            continue
        for v, w in graph[u]:
            nv = min(d, w, node_map[v]["expires"])
            if nv > dist[v]:
                dist[v] = nv
                heapq.heappush(heap, (-nv, v))

