    def best_path(target, B):
        # Restrict to nodes/edges whose expiry >= B; find fewest edges, then
        # lexicographically smallest complete node-id path.
        rev = {}
        for u, outs in graph.items():
            if node_map[u]["expires"] < B:
                continue
            for v, w in outs:
                if w >= B and node_map[v]["expires"] >= B:
                    rev.setdefault(v, []).append(u)

        dist_to_target = {target: 0}
        q = deque([target])
