            u = q.popleft()
            d = dist_to_target[u]
            for prev in rev.get(u, ()):
                if prev not in dist_to_target:
                    dist_to_target[prev] = d + 1
                    q.append(prev)

        D = None
        for r in surviving_roots:
            if r in dist_to_target:
                if D is None or dist_to_target[r] < D:
                    D = dist_to_target[r]
        if D is None:
            raise ValueError("unreachable target during path reconstruction")

        start = min(r for r in surviving_roots if dist_to_target.get(r) == D)
        path = [start]
        cur = start
        rem = D
        while rem > 0:
            candidates = []
            for v, w in graph.get(cur, ()):
                if w >= B and node_map[v]["expires"] >= B and node_map[cur]["expires"] >= B:
                    if dist_to_target.get(v) == rem - 1:
                        candidates.append(v)
            if not candidates:
                raise ValueError("path reconstruction failed")
            nxt = min(candidates)
            path.append(nxt)
            cur = nxt
            rem -= 1
        return path

    trusted = []
    untrusted = []
    for nid in sorted(node_map.keys()):
        if nid not in surviving:
            untrusted.append(nid)
            continue
        if dist[nid] <= 0:
            untrusted.append(nid)
            continue
        B = dist[nid]
        path = best_path(nid, B)
        trusted.append({"id": nid, "path": path, "valid_until": B})

    trusted.sort(key=lambda x: x["id"])
    untrusted.sort()

    return {
        "name": contract["name"],
        "result": {"trusted": trusted, "untrusted": untrusted},
    }

