import fnmatch


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _nonempty(value):
    return isinstance(value, str) and value.strip() != ""


def _specificity(resource, action):
    # Number of characters in resource+action that are not glob metacharacters.
    return sum(1 for ch in resource + action if ch not in "*?[]")


def transform(payloads, contract):
    if contract.get("operation") != "policy_precedence":
        raise ValueError("unsupported operation: %r" % contract.get("operation"))
    if not isinstance(payloads, list) or len(payloads) != 1:
        raise ValueError("policy_precedence expects exactly one input payload")
    payload = payloads[0]
    if not isinstance(payload, dict):
        raise ValueError("policy_precedence payload must be an object")

    # ---- rules ----
    if "rules" not in payload:
        raise ValueError("missing 'rules'")
    rules_raw = payload["rules"]
    if not isinstance(rules_raw, list):
        raise ValueError("'rules' must be a list")
    rules = []
    seen_ids = set()
    for r in rules_raw:
        if not isinstance(r, dict):
            raise ValueError("rule must be an object")
        rid = r.get("id")
        if not _nonempty(rid):
            raise ValueError("rule id must be a non-empty string")
        if rid.strip() in seen_ids:
            raise ValueError("duplicate rule id: %r" % rid)
        seen_ids.add(rid.strip())
        resource = r.get("resource")
        if not _nonempty(resource):
            raise ValueError("rule resource must be a non-empty string")
        action = r.get("action")
        if not _nonempty(action):
            raise ValueError("rule action must be a non-empty string")
        priority = r.get("priority")
        if not _is_int(priority):
            raise ValueError("rule priority must be an int")
        effect = r.get("effect")
        if effect not in ("allow", "deny"):
            raise ValueError("rule effect must be 'allow' or 'deny'")
        rules.append({
            "id": rid,
            "resource": resource,
            "action": action,
            "priority": priority,
            "effect": effect,
            "specificity": _specificity(resource, action),
        })

    # ---- requests ----
    if "requests" not in payload:
        raise ValueError("missing 'requests'")
    requests_raw = payload["requests"]
    if not isinstance(requests_raw, list):
        raise ValueError("'requests' must be a list")
    requests = []
    for q in requests_raw:
        if not isinstance(q, dict):
            raise ValueError("request must be an object")
        resource = q.get("resource")
        action = q.get("action")
        if not _nonempty(resource):
            raise ValueError("request resource must be a non-empty string")
        if not _nonempty(action):
            raise ValueError("request action must be a non-empty string")
        requests.append({"resource": resource.strip(), "action": action.strip()})

    decisions = []
    allow = 0
    deny = 0
    for q in requests:
        matching = [
            r for r in rules
            if fnmatch.fnmatchcase(q["resource"], r["resource"])
            and fnmatch.fnmatchcase(q["action"], r["action"])
        ]
        if not matching:
            effect = "deny"
            rule_id = None
        else:
            matching.sort(key=lambda r: (
                -r["priority"],
                -r["specificity"],
                0 if r["effect"] == "deny" else 1,
                r["id"],
            ))
            winner = matching[0]
            effect = winner["effect"]
            rule_id = winner["id"]
        decisions.append({
            "resource": q["resource"],
            "action": q["action"],
            "effect": effect,
            "rule_id": rule_id,
        })
        if effect == "allow":
            allow += 1
        else:
            deny += 1

    return {
        "name": contract["name"],
        "result": {"decisions": decisions, "allow": allow, "deny": deny},
    }

